def max_difference(pairs):
    if not pairs:
        return 0
    min_price = float('inf')
    max_difference = 0
    for pair in pairs:
        min_price = min(min_price, pair[0])
        max_difference = max(max_difference, pair[1] - min_price)
    return max_difference

def max_difference(pairs):
    if not pairs:
        return 0
    max_difference = 0
    for i in range(len(pairs)):
        for j in range(i+1, len(pairs)):
            max_difference = max(max_difference, abs(pairs[i][0] - pairs[j][1]))
    return max_difference

